sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var manager = g_form.getValue("base_manager");

	if (!manager) {
		return;
	}

	var ga = new GlideAjax("x_1519575_traini_1.BaseUtils");
	ga.addParam("sysparm_name", "validateBaseManager");
	ga.addParam("sysparm_manager", manager.toString());

	ga.getXMLAnswer(function(answer) {
		if (answer === "true") {
			g_form.setValue("base_manager", "");
			g_form.showErrorBox("base_manager", "This member is already a base manager for a different base.", true);
		}
	});

}
